    _issue_orbit(19)
    _issue_orbit(20)
    _issue_orbit(21)
    _issue_orbit(22)
    _drain_step([18, 19, 20, 21, 22])

    # ---- OrbitGreedy step 5 (4 orbit(s)) ----
